  "CO₂ received and sent on": "接收并转出的 CO₂",
  "CO₂ released by the chemistry rather than by burning fuel — flux decomposition, electrode consumption, carbon injection. Pick the material and the quantity; the figure is computed, not typed. Zero rows recorded is a common and correct answer.":
    "由化学反应而非燃烧燃料释放的 CO₂ — 熔剂分解、电极消耗、喷碳。选择材料并填写数量，数值由系统计算而非手填。没有记录任何行是常见且正确的答案。",
  "CO₂ released when a carbonate decomposes — limestone, dolomite, magnesite, soda ash. Pick the material and the tonnes; the figure is the quantity times the EU factor for that material. Leave it empty if the plant adds none.":
    "碳酸盐分解时释放的 CO₂ — 石灰石、白云石、菱镁矿、纯碱。选择材料并填写吨数，数值为数量乘以该材料的欧盟系数。如果工厂没有添加，请留空。",
  "CO₂ sent on": "转出的 CO₂",
  "CO₂ sent on for storage or permanent use": "转出用于封存或永久利用的 CO₂",
  "CO₂ that came in from another installation, or went out for permanent storage or to be chemically bound in a product.":
    "从其他设施转入的 CO₂，或转出用于永久封存或化学固定于产品中的 CO₂。",
  "Calorific value": "热值",
