  "Carbon that goes in is counted as emitted. Carbon that leaves in the product, the slag or a by-product is not — it comes off.":
    "进入的碳按排放计算；随产品、炉渣或副产品离开的碳不计入排放，需扣除。",
  "Carbon that stays in it:": "留存于其中的碳：",
