  Entry: "条目",
  "Established by field measurement to industry best practice, within ±15%, and renewed at least every three years or when the cells change. Attach the measurement report on the Documents step.":
    "须按行业最佳实践通过现场实测得出，误差在 ±15% 以内，且至少每三年或电解槽变更时更新一次。请在“文件”步骤上传测量报告。",
  "Every answer is saved to Certrace for the company that sent you this link — you can close this page and come back to it from any device.":
    "您的每个答案都会保存到 Certrace，供发送此链接的公司查看 — 您可以关闭本页，之后在任何设备上重新打开继续填写。",
  "Every answer stays in this browser until Certrace’s hosted service is connected.":
    "在 Certrace 云服务接入之前，您的所有答案只保存在这台浏览器中。",
  "Every conversation you have with Cera is kept here, so you can pick it up again.":
    "您与 Cera 的每次对话都保存在这里，可随时继续。",
  "Every fuel burned inside the boundary across the whole year, and the meter that measures each one.":
    "全年在边界内燃烧的所有燃料，以及用于计量每种燃料的仪表。",
  "Every fuel burned inside the boundary this month, with the quantity as your invoice states it.":
    "本月在边界内燃烧的所有燃料，数量以发票上的为准。",
  "Every fuel used across the year, not only this month. Choosing one adds its row to the monthly readings.":
    "全年使用过的所有燃料，不只是本月。选择某种燃料后，会在月度读数中新增对应的一行。",
  "Every process on the list is already declared outside the boundary. If that is right, nothing is inside it — check the “Processes included” list above.":
    "清单中的所有工序都已声明在边界之外。如果这是正确的，则边界内没有任何工序 — 请检查上面的“纳入的工序”清单。",
  "Everything needed is in": "所需内容均已齐全",
  "Everything saves as you type, so you can leave and come back on this machine. Nothing is submitted until you sign on the last step.":
    "输入的内容会自动保存，因此您可以离开，之后在这台设备上继续。在最后一步签署之前，不会提交任何内容。",
