  Gas: "气体",
  "Gas main to reheat furnace RF-1, upstream of the burner skid":
    "通往再加热炉 RF-1 的煤气总管，位于烧嘴撬块上游",
  "Gas meter failed; replaced 14 March": "气表故障；3 月 14 日已更换",
  "Geographic coordinates": "地理坐标",
  "Give Cera one file and it fills in the month":
    "给 Cera 一个文件，它会帮您填写当月数据",
  "Give me a file — I'll fill in the month": "给我一个文件 — 我来填写当月数据",
  "Gives an oxidation factor of": "得出的氧化系数为",
  "Go to exporter portal": "前往出口商门户",
  "Go to the first thing to fix": "前往第一个待修正项",
  "Goes in — counted as emitted": "输入 — 按排放计算",
  Good: "货物",
  "Goods in scope": "纳入范围的货物",
  "Goods that are not CBAM goods — only if the plant makes any. Leave empty if it does not.":
    "非 CBAM 货物 — 仅在工厂生产时填写，没有则留空。",
  "Got it": "知道了",
  Grade: "牌号",
  "Greenhouse gas": "温室气体",
  "Grid emission factor": "电网排放因子",
  "Ground for excluding it": "排除理由",
  "Grouped by who usually holds each document — Operations, Finance, Suppliers, Lab, and Organisation-level — so nothing has to be chased from a list that mixes all five together.":
    "按通常持有文件的部门分组 — 运营、财务、供应商、实验室和公司层面 — 这样不必从混在一起的清单里逐项追查。",
  "Guessed from the file name — check what it is.":
    "根据文件名推测 — 请核实它是什么。",
  "Have the documents already?": "已经有文件了吗？",
  Heat: "热力",
  "Heat that came in from, or went out to, another installation — and what was made and used on site.":
    "从其他设施输入或输出到其他设施的热力 — 以及在现场产生并使用的热力。",
  "Here is what AI found and where each value will go. Nothing is saved until you confirm.":
    "这是 AI 识别出的内容以及每个数值将填入的位置。确认之前不会保存任何内容。",
  Hide: "隐藏",
  History: "历史记录",
  "How PFC is monitored": "PFC 如何监测",
  "How direct emissions are determined": "直接排放的确定方法",
  "How often one happens, on average. 0 if none.":
    "平均每隔多久发生一次。没有则填 0。",
  "How the anode effects are counted": "阳极效应的计量方式",
  "How the duct's collection efficiency was determined":
    "烟道收集效率的确定方式",
  "How the figure was estimated": "该数值是如何估算的",
  "How the quantity is found": "数量如何得出",
  "How to fill it.": "填写方法。",
  "How you make it — tells the exporter which precursors should sit above you.":
    "您的生产方式 — 用于告诉出口商，哪些前体应当位于您的上游。",
  "I have my own measured factors": "我有自己实测的系数",
  "I read your documents for this month and fill them in.":
    "我会读取您本月的文件并帮您填写。",
  "I've checked this — file it": "我已核对 — 请归档",
  "If a revision is needed, you’ll get an email — only the flagged fields unlock.":
    "如需修改，您会收到电子邮件 — 只有被标记的字段会解锁。",
  "If any of this is wrong, tell {exporter} before you answer — the figures below are only valid for this good.":
    "如果以上有任何错误，请在回答前告知 {exporter} — 下面的数据只对该货物有效。",
  "If it is not reported, the importer is not let off — they fall back to a default set high enough that real data is nearly always cheaper. So what you enter here has a price attached, in both directions.":
    "如果不申报，进口商也不会被豁免 — 而是适用被设定得足够高的默认值，因此实际数据几乎总是更便宜。所以您在这里填写的内容，无论高低都关系到成本。",
  "If this good is made from pig iron or DRI, what reduced the iron ore? For a pure scrap-EAF route, choose “None” — that is a complete and expected answer.":
    "如果该货物由生铁或直接还原铁生产，铁矿石是用什么还原的？如果是纯废钢电弧炉路线，请选“无” — 这是完整且符合预期的答案。",
  "If this site has no code yet:": "如果该地点还没有代码：",
  "In the duct": "在烟道中",
  "In the meantime, use the code of the nearest listed town — an approximate but real code is more useful to a declarant than a blank field, and the coordinates below pin the exact location anyway.":
    "在此期间，请使用最近的已列出城镇的代码 — 近似但真实的代码比空白更有用，而且下方的坐标本来就能精确定位。",
  "In the terms your invoices use.": "请使用您发票上的叫法。",
  "In the words your invoices use.": "请使用您发票上的叫法。",
  "In tonnes of CO₂ equivalent.": "单位：吨 CO₂ 当量。",
  Include: "纳入",
  Indirect: "间接",
  "Indirect SEE": "间接单位内含排放",
  Installation: "设施",
  "Installation details": "设施详情",
  "Installation it comes from": "来源设施",
  "Installation reference": "设施编号",
  Instrument: "仪表",
  "Instruments — electricity": "仪表 — 电力",
  "Instruments — fuels": "仪表 — 燃料",
  "Internal authorisation": "内部授权",
  Invite: "邀请",
  "Invite a colleague": "邀请同事",
  "Invoice no. / meter id": "发票号 / 仪表编号",
  "It goes to the exporter as a request. They decide — nothing is unlocked until they say yes.":
    "这会作为请求发送给出口商，由他们决定 — 在对方同意之前不会解锁。",
  "It has to be unique.": "必须唯一。",
  "It identifies WHERE the goods were produced. Use the code for the town or port the installation sits in — not your head office, and not the port the goods leave from if that is somewhere else.":
    "它标明货物在哪里生产。请使用设施所在城镇或港口的代码 — 不是总部所在地，也不是货物出运的港口（如果两者不同）。",
  "It is needed": "需要填写",
  "It is not the same thing as the electricity metering point on the card below. That one is a revenue meter; this one is a sampling location on a flue.":
    "这与下面卡片中的电力计量点不是一回事。那是结算用电表；这里是烟道上的采样位置。",
  "Its name or tag.": "它的名称或位号。",
  "Jump to first flagged field": "跳到第一个被标记的字段",
  Keep: "保留",
  "Laem Chabang is": "例如：林查班港为",
  "Last calibrated": "上次校准",
  "Last calibration date": "上次校准日期",
  "Last measured": "上次测定",
  "Lat, long of the main emission source.": "主要排放源的经纬度。",
  Later: "稍后",
  Latitude: "纬度",
  "Latitude — main emission source": "纬度 — 主要排放源",
  "Leave blank if chromium is only a trace element.":
    "如果铬只是痕量元素，请留空。",
  "Leave blank if manganese is only a trace element.":
    "如果锰只是痕量元素，请留空。",
  "Leave blank if nickel is only a trace element.":
    "如果镍只是痕量元素，请留空。",
  "Leave empty if it is the installation's own country.":
    "如果与设施所在国相同，请留空。",
  "Leave empty if the plant melts no scrap.": "如果工厂不熔炼废料，请留空。",
  "Leave empty to use the composition, or the typical value.":
    "留空则按成分或典型值计算。",
  "Leave on 1 unless you measure the carbon left in the ash — 1 is always allowed.":
    "除非您测量了灰中残留的碳，否则保持为 1 — 填 1 始终是允许的。",
  "Leaves — carbon stays in it": "输出 — 碳留存于其中",
  "Leaving in the product and by-products": "随产品和副产品带出",
  "Legal company name": "公司法定名称",
  Line: "产线",
  "Lines of cells": "电解槽系列数",
  "Locked to the EU standard value.": "已锁定为欧盟标准值。",
  "Locked to the published country default.": "已锁定为已公布的国家默认值。",
  "Locked — not part of this revision.": "已锁定 — 不属于本次修订范围。",
