  "Mass balance": "质量平衡",
  "Mass in tonnes": "质量（吨）",
  Material: "材料",
  "Mean of Feb and Apr consumption, scaled by March's billet tonnage":
    "2 月和 4 月用量的平均值，按 3 月钢坯产量折算",
  "Measurable heat": "可计量热力",
  "Measure your own factors": "测定您自己的系数",
  "Measured emissions": "实测排放",
  "Measured from the ash analysis": "由灰分分析测得",
  "Measured in the duct and at the roof vents during the 2025 survey of potline 2.":
    "在 2025 年对 2 号电解槽系列的调查中，于烟道和屋顶通风口处测得。",
  "Measured source": "实测排放源",
  "Measurement point": "测量点",
