  "Pick the cell type": "选择电解槽类型",
  "Pick the closest match — the list is written in the names Thai plants actually use. Then name the meter: the feeder, the meter number, whatever appears on the bill.":
    "请选择最接近的一项 — 清单采用泰国工厂实际使用的叫法。然后填写仪表：馈线、电表编号，或账单上出现的任何标识。",
  "Pick the fuel first — the standard value fills in.":
    "请先选择燃料 — 标准值会自动填入。",
  "Plain English. Leave it empty if the month was ordinary.":
    "请用简明英文书写。如果当月一切正常，请留空。",
  "Plants start from the EU factors for the cell type. Their own factors, measured in the field to within ±15%, replace them and are renewed at least every three years.":
    "工厂从该电解槽类型的欧盟系数起步。经现场测定（误差在 ±15% 以内）的自有系数可取而代之，并至少每三年更新一次。",
  "Please write {scope} in English": "请用英文填写{scope}",
