  "{count} rows the arithmetic refused — the balance would print short by them.":
    "有 {count} 行无法计算 — 平衡表会因此少计这些行。",
  "{count} template fields still blank — {first}":
    "还有 {count} 个模板字段为空 — {first}",
  "{covered} of {total} have a document behind them.":
    "{total} 项中有 {covered} 项附有文件依据。",
  "{covered} of {total} submitted months carry fuel rows.":
    "已提交的 {total} 个月中有 {covered} 个月含有燃料行。",
  "{done} of {total} read": "已读取 {done}/{total}",
  "{exporter} needs your carbon data.": "{exporter} 需要您的碳数据。",
  "{exporter} uses a good you make as an input and has asked for your final, verified figure for the reporting year. One request, answered once — nothing is collected month by month. Please answer":
    "{exporter} 把您生产的一种货物用作投入物，并请您提供报告年度经核查的最终数据。只有一次请求、只需回答一次 — 不按月收集。请回答",
  "{from} to {to}. Fixed at creation and printed as it stands.":
    "{from} 至 {to}。创建时已固定，将按原样打印。",
  "{n} documents attached": "已附 {n} 份文件",
  "{n} documents waiting for your check": "{n} 份文件等待您核对",
  "{n} not needed — won't be filed": "{n} 份无需 — 不会归档",
  "{n} still need your tick — they stay here for later.":
    "还有 {n} 项需要您勾选 — 它们会保留在这里供稍后处理。",
  "{n} things to fix": "有 {n} 项待修正",
  "{route} is not a production route for {category}. The table will print a contradiction.":
    "{route} 不是 {category} 的生产路线。该表将出现矛盾的内容。",
  "{share}% of the year rests on estimates — past the {threshold}% self-check threshold.":
    "全年有 {share}% 的数据依赖估算 — 已超过 {threshold}% 的自查阈值。",
  "{total} ({required} required)": "{total}（其中必填 {required}）",
  "± %, from the maker or the calibration certificate.":
    "± %，取自制造商或校准证书。",
  "· enter your output in Production to get the per-tonne figure":
    "· 在“产量”中填写您的产出，即可得到每吨数值",
  "· optional": "· 选填",
  "· our own installation": "· 我们自己的设施",
  "— an EU-accredited verifier reads it. Numbers and dates stay as they are.":
    "— 由欧盟认可的核查员阅读。数字和日期保持原样。",
  "— no password, no server session, nothing sent anywhere. It only pre-fills this installation’s details the next time this SAME link is opened on this SAME device or browser.":
    "— 无需密码，没有服务器会话，不向任何地方发送任何内容。它只会在下次于同一设备或浏览器打开同一链接时，预先填入该设施的信息。",
  "“Estimated” on its own is a finding. HOW it was estimated — from the mean of the months either side, normalised to production — is an answer.":
    "只写“估算”本身就是一个核查发现项。说明是如何估算的 — 例如取前后月份平均值再按产量折算 — 才是答案。",
  "“Grid — Provincial Electricity Authority (PEA)”, meter PEA 3392011 on main incomer MDB-1.":
    "“电网 — 地方电力局（PEA）”，主进线 MDB-1 上的电表 PEA 3392011。",
