  "Sample numbers": "示例数字",
  "Sample numbers.": "示例数字。",
  "Nothing has been submitted yet, so this shows a made-up estate to give you the picture. Your own data is not touched.":
    "尚未提交任何数据，因此这里显示的是虚构的整体情况，供您参考。您自己的数据不会被改动。",
