  "Asked — waiting": "已索取 — 等待中",
  "asked, but not an Annex IV item": "已索取，但不属于附件四的项目",
  "Asking for a revision reopens the conversation and puts it back with the supplier.":
    "申请修改会重新开启对话，并退回给供应商。",
  "assign from a declaration": "从申报中分配",
  "at {time}": "今天 {time}",
