  "Decimal degrees with six decimals, of the main emission source — the stack of the furnace that dominates the figures, not the front gate.":
    "主要排放源的十进制度坐标，保留六位小数 — 指主导数字的炉子烟囱，而不是厂区大门。",
  "Declarant-specific addendum": "申报人专属补充文件",
  "Declaration created.": "申报已创建。",
  "Declaration not found": "未找到申报",
  "Declaration status": "申报状态",
  "Dedicated implementation": "专属实施",
  "Default 1.": "默认 1。",
  "Default value in use": "正在使用的默认值",
  "Default value justification": "默认值的理由",
  "default values used for some precursors": "部分前体使用了默认值",
  "Defensible when consumption tracks output closely. Show the ratio you used and the period it came from.":
    "当消耗量与产量紧密同步时，这是站得住脚的。请显示您使用的比值及其来源期间。",
  "Deliberately unflattering by design, which is why it is safe. Expect no challenge, but it costs you.":
    "特意设计得不讨好，因此才安全。预计不会被质疑，但会增加您的成本。",
  "Delivery date": "交货日期",
  "Delivery note for 12,000 litres of diesel B7 on 18 April 2026. No price on the note.":
    "2026 年 4 月 18 日 12,000 升 B7 柴油的送货单。单上无价格。",
  "Derived automatically: own direct + own indirect + precursor contribution":
    "自动得出：自身直接 + 自身间接 + 前体贡献",
  "Derived from the MMD's data-gap register. Nothing to fill in — it moves when the gaps do.":
    "来自 MMD 的数据缺口登记。无需填写 — 缺口变化时它会随之变化。",
  "Describe it in the field below.": "请在下方字段中说明。",
  "Describe it in the field that appears.": "请在出现的字段中说明。",
  "Describe it in the terms your invoices use": "请用您发票上的措辞描述",
  "Describe the site and list, in order, the production processes inside the boundary.":
    "描述站点，并按顺序列出边界内的生产工艺。",
  "Described in the final monitoring methodology": "在最终监测方法中说明",
  "Deselect {field}": "取消选择 {field}",
  "Designated checks": "指定检查",
  "details missing": "详情缺失",
  "Determination method (actual / default)": "确定方法（实际 / 默认）",
  "Digits only after the country code — spaces, brackets and dashes are fine, letters are not.":
    "国家代码后只能填数字 — 空格、括号和短横线可以，字母不行。",
  "Direct (Scope 1) emissions": "直接（范围 1）排放",
  "Direct & indirect emissions per tonne.": "每吨产品的直接与间接排放。",
  "Direct emissions of YOUR production step only — precursors are added separately below":
    "仅为您自己生产环节的直接排放 — 前体在下方另行加入",
  "Direct specific emissions — own process (tCO₂e/t)":
    "直接特定排放 — 自身工艺（tCO₂e/吨）",
  "Direct, indirect and precursor emissions": "直接、间接和前体排放",
  "Display currency": "显示货币",
  "Display only — your filings always carry the unit the EU template requires.":
    "仅用于显示 — 您的申报始终采用欧盟模板要求的单位。",
  "Document added": "已添加文件",
  "Document read by AI": "文件已由 AI 读取",
  "document(s)": "份文件",
  "Documents attached": "已附文件",
  "Documents attached to the right month": "文件已附在正确的月份",
  "Documents expected, month by month": "按月预期的文件",
  "Documents in this index": "本索引中的文件",
  "Documents uploaded": "已上传的文件",
  "Does CO₂ transfer apply?": "是否涉及 CO₂ 转移？",
  "Download Monitoring Methodology Documentation": "下载监测方法文档",
  "Download one, then drop it above. Each holds only a few readings — enough to see how it works.":
    "下载一个，然后拖到上方。每个只含少量读数 — 足够看出它如何运作。",
  "Downloading documents for {name}…": "正在下载 {name} 的文件…",
  "Downloading report for {name}…": "正在下载 {name} 的报告…",
  draft: "草稿",
  "Draft — not finalised": "草稿 — 未定稿",
  "Draft · not yet sent": "草稿 · 尚未发送",
  "Draft pack downloaded": "草稿资料包已下载",
  "Draw the line around what you are reporting. A verifier's first question is always what happens on this site that is NOT in these numbers, and why that is correct.":
    "围出您所申报的范围。核查员的第一个问题永远是：这个站点上还发生了哪些不在这些数字里的事，为什么这样做是正确的。",
  "Drawn from the public grid. Factor is the published country default — locked, never typed.":
    "取自公共电网。排放因子为公布的国家默认值 — 已锁定，不可手填。",
  "Drop this month's bills, fuel invoices and ERP exports. AI reads each one, files it and fills the matching figures. You check everything before it is saved — AI can make mistakes.":
    "拖入本月的账单、燃料发票和 ERP 导出文件。AI 逐份读取、归档并填写对应数字。保存前请您全部核对 — AI 可能出错。",
  due: "到期",
  Due: "到期",
  "Due now": "现已到期",
  "e.g. ABC Buyer Carbon Data Request": "例如：ABC 买家碳数据请求",
  "e.g. Annual CBAM carbon data for our EU steel exports. Please report at installation level.":
    "例如：我们出口欧盟的钢材的年度 CBAM 碳数据。请按设施层级报告。",
  "e.g. CBAM 2026 Annual": "例如：CBAM 2026 年度",
  "e.g. Eastern Steel Mill": "例如：东方钢厂",
  "e.g. Please use installation-level actual data where possible. Contact us if you need help.":
    "例如：请尽可能使用设施层级的实际数据。如需帮助请联系我们。",
  "e.g. Steel billet": "例如：钢坯",
  "e.g. Thai Special Steel": "例如：泰国特种钢",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — a declarant addendum where electricity goes to the EU — and, beside them, the verification reports of your precursors' installations and the supporting evidence. It covers every product the site makes, and downloads once all of it is complete.":
    "您申报的每个设施每年提交一份资料包：监测计划、运营方排放报告和汇总报告 — 电力输往欧盟时附申报人补充文件 — 以及并列的前体设施核查报告和支持证据。它涵盖该站点生产的所有产品，全部完成后方可下载。",
  "Each installation you report on hands over one package a year: the monitoring plan, the operator's emissions report and the summary report — and a declarant addendum where electricity goes to the EU. It covers every product the site makes, and downloads once all of it is complete.":
    "您申报的每个设施每年提交一份资料包：监测计划、运营方排放报告和汇总报告 — 电力输往欧盟时附申报人补充文件。它涵盖该站点生产的所有产品，全部完成后方可下载。",
  "Each is filed against the figure it supports.":
    "每份文件都归档在其所支持的数字之下。",
  "Each one links to the screen that fixes it.":
    "每一项都链接到可修复它的页面。",
  "Each product has its own parameters.": "每个产品有各自的参数。",
  "Economic activity": "经济活动",
  "Edit buyer": "编辑买家",
  "Editing afterwards forks the next version, so the one a verifier read stays as it was.":
    "事后编辑会生成新版本，因此核查员已读过的版本保持原样。",
  "Editing forks a new version.": "编辑会生成新版本。",
  "Electricity bill": "电费账单",
