  "Fertilisers: nitrogen content, purity or concentration.":
    "化肥：氮含量、纯度或浓度。",
  "File all ready ({n})": "提交全部已就绪项（{n}）",
  "File all ready ({n}) now": "立即提交全部已就绪项（{n}）",
