  "Filed packages": "已提交的资料包",
  "filled box: required": "实心框：必填",
  "Filled by AI from {file}. AI can make mistakes — check it against the document and edit it if it is wrong.":
    "由 AI 根据 {file} 填写。AI 可能出错 — 请对照文件核对，有误请修改。",
  Fills: "填入",
  "Fills into the questionnaire": "填入问卷",
  "Finalise the methodology: it describes how the emissions of each production process are attributed.":
    "请定稿方法：它描述了各生产工艺的排放如何归属。",
  "Finalise the methodology: that stamps its version number and date.":
    "请定稿方法：这会固定其版本号和日期。",
  "Finalise the MMD": "定稿 MMD",
  Finance: "财务",
  "Finished product": "成品",
  "First that has data": "首个有数据的",
  "Fix the precursor chain": "修正前体链",
  "Flag new rule changes": "标记新的规则变更",
  "Flag new rule changes on my button": "在我的按钮上标记新的规则变更",
  "For a power purchase agreement, name the producer.":
    "购电协议请注明发电方。",
  "For each source stream say where its calculation factor comes from and how often it is sampled.":
    "对每个源流，说明其计算因子来自何处以及取样频次。",
  "For each thing you measure: the instrument, how often it is read, when it was last calibrated, and where its factor comes from. An uncalibrated instrument is the fastest route to a qualified opinion.":
    "对您测量的每一项：仪器、读数频次、上次校准时间、因子来源。未校准的仪器是得到保留意见的最快途径。",
  "For example limestone, electrodes, reducing agents.":
    "例如石灰石、电极、还原剂。",
  "For example natural gas, coal, diesel — most important first.":
    "例如天然气、煤、柴油 — 最重要的在前。",
  "For fuels: quantity × net calorific value × emission factor × oxidation factor.":
    "燃料：数量 × 净热值 × 排放因子 × 氧化因子。",
  "For now this product uses the default value for this precursor":
    "目前本产品对该前体使用默认值",
  "For process materials: quantity × emission factor × conversion factor.":
    "工艺物料：数量 × 排放因子 × 转换因子。",
  "Forced to 0 — scrap carries no embedded emissions.":
    "已强制为 0 — 废钢不带隐含排放。",
  "Form of carbon price (ETS / tax / levy)": "碳价形式（ETS / 税 / 费）",
  "Format: 2-letter country + 6–15 characters, e.g. DE551234567890":
    "格式：2 位国家代码 + 6–15 个字符，例如 DE551234567890",
  "Freeze calculation": "冻结计算",
  "Freezing captures the activity dataset, the precursor tree, the engine version and every output under one hash.":
    "冻结会将活动数据集、前体树、引擎版本和所有输出固定在同一个哈希下。",
  fresh: "新鲜",
  "From — country of origin": "来自 — 原产国",
  "From 20+ CN codes": "CN 编码 20 个以上",
  "From the CBAM catalogue — locked to the CN code beside it.":
    "来自 CBAM 目录 — 与旁边的 CN 编码锁定。",
  "From the CBAM catalogue — locked to the product beside it.":
    "来自 CBAM 目录 — 与旁边的产品锁定。",
  "From this supplier's own CBAM communication.":
    "来自该供应商自己的 CBAM 通报。",
  "Fuel CO₂": "燃料 CO₂",
  "Fuel consumption record": "燃料消耗记录",
  "Fuel invoice / delivery note": "燃料发票 / 送货单",
  "Fuel is recorded but production is zero. If the plant ran, the tonnage is missing; if it was idle, the fuel belongs outside the boundary and the methodology should say so.":
    "已记录燃料但产量为零。如果工厂运行过，说明缺少吨数；如果停产，燃料应归于边界之外，方法中应说明。",
  "Fuel quantity not written — the document says {docUnit}, the row is in {rowUnit}":
    "燃料数量未写入 — 文件为 {docUnit}，该行为 {rowUnit}",
  "Fuel quantity: {qty} {unit}": "燃料数量：{qty} {unit}",
  "Fuel types, factors, NCVs and the electricity factor were cloned.":
    "燃料类型、因子、净热值和电力因子已复制。",
  "Fuel types, factors, NCVs and the electricity factor were cloned. Quantities were NOT — enter this month's readings.":
    "燃料类型、因子、净热值和电力因子已复制，但数量未复制 — 请录入本月读数。",
  "Fuel, power and materials the figure is derived from.":
    "数字所依据的燃料、电力和物料。",
  fuels: "燃料",
  "Fuels are declared but no instrument measures them. Add one row per fuel — what is measured, on what, how often, and when it was last calibrated.":
    "已声明燃料，但没有仪器测量它们。请为每种燃料添加一行 — 测量什么、用什么测、多久读一次、上次校准时间。",
  "fuels, standard method: quantity × net calorific value × emission factor × oxidation factor":
    "燃料，标准方法：数量 × 净热值 × 排放因子 × 氧化因子",
  "Full access · billing": "完全权限 · 账单",
  "Full address of the installation, in English": "设施完整地址（英文）",
  "Full address of the operator, in English": "运营方完整地址（英文）",
  "Full street address of the production site": "生产站点的完整街道地址",
  "Full-year projection": "全年推算",
  "Furnace fuel. The lowest-intensity aluminium route by a large margin.":
    "炉用燃料。迄今为止碳强度最低的铝路线。",
  "Further processing — casting, homogenising, rolling, extruding, annealing or coating. The metal comes in as a precursor.":
    "深加工 — 铸造、均质化、轧制、挤压、退火或涂层。金属作为前体进入。",
  "Further processing — reheating, rolling, forging, annealing, drawing, pickling or coating. The steel itself comes in as a precursor.":
    "深加工 — 再加热、轧制、锻造、退火、拉拔、酸洗或涂层。钢本身作为前体进入。",
  "G J Steel is overdue": "G J Steel 已逾期",
  "generated {date}": "生成于 {date}",
  "Generated on site. Factor is derived from the fuels burned to generate it — see the fuel rows above, flagged for self-generation.":
    "现场发电。因子由发电所燃烧的燃料推算 — 见上方标记为自发电的燃料行。",
  "Geographical coordinates of the installation's main emission source":
    "设施主要排放源的地理坐标",
  "Geolocation & due-diligence engine in build — live Q4 2026.":
    "地理定位和尽职调查引擎开发中 — 2026 年第四季度上线。",
  "Give every instrument a calibration date in the methodology.":
    "请在方法中为每台仪器填写校准日期。",
  "Give every product report a CN code and a route.":
    "请为每份产品报告填写 CN 编码和路线。",
  "Go to declarations": "前往申报",
