  "Grid / PPA factor and its documented source":
    "电网 / 购电协议因子及其记录在案的来源",
  "Grid electricity": "电网电力",
  "Grid electricity is not a source stream of direct emissions.":
    "电网电力不是直接排放的源流。",
  "Guessed from the file name": "根据文件名推测",
  "Guessed from the file name only. Nothing inside the file was read, so no values were proposed.":
    "仅根据文件名推测，未读取文件内容，因此没有给出任何数值建议。",
  "Guided setup + data migration": "引导式设置 + 数据迁移",
  "H1 (Jan–Jun)": "上半年（1–6 月）",
  "H2 (Jul–Dec)": "下半年（7–12 月）",
