  "How each precursor was produced, where known":
    "每个前体的生产方式（如已知）",
  "How much carbon is embedded in what you make, and how far that sits under the EU default a buyer would otherwise have to assume. Pick a year, then a product to negotiate with — or read the whole year at once.":
    "您所生产产品隐含了多少碳，以及它比买家原本不得不假定的欧盟默认值低多少。先选一个年度，再选一个要谈判的产品 — 或一次读完全年。",
  "How much of each bought-in CBAM input arrived this month.":
    "本月到货的每种外购 CBAM 投入物的数量。",
  "How much of each input arrived in this month, as your goods-received records state it.":
    "按您的收货记录所示，本月到货的每种投入物的数量。",
  "How sure the detection is": "检测的把握程度",
  "How the attributed direct and indirect emissions of each production process were calculated":
    "各生产工艺归属的直接和间接排放是如何计算的",
  "How the plant measures. Written once, changed only when the plant changes.":
    "工厂如何测量。只写一次，工厂有变化时才修改。",
  "If a buyer asked for proof today, could we send it":
    "如果买家今天要证明，我们能否提供",
  "If any figure changes after this — a month re-submitted, a precursor corrected, a document added — the sign-off lapses and has to be repeated. That is deliberate: it is what stops a signature outliving the numbers it was given for.":
    "此后若有任何数字变化 — 重新提交某个月、更正某个前体、新增某份文件 — 签署即告失效，须重新签署。这是有意为之：它能防止签名比其所依据的数字存活得更久。",
  "If none is burned, answer No; if some is, say how you demonstrate it.":
    "若未燃烧则回答“否”；若有燃烧，请说明如何证明。",
  "If relevant, a list of the non-CBAM goods produced per production process and the quantity produced":
    "如相关，列出各生产工艺所生产的非 CBAM 产品及产量",
  "If the answer is yes, describe each analyser and where it samples in the methodology.":
    "如果答案为是，请在方法中描述每台分析仪及其取样位置。",
  "If the precursor sent you their figures and verification report some other way, enter or attach them here. The same checks apply as if they had filled it in themselves.":
    "如果前体通过其他方式把数字和核查报告发给了您，请在此录入或附上。适用的检查与其自行填写时相同。",
  "If this site also makes products outside CBAM scope, list them so a verifier can confirm the boundary in this report covers only the CBAM good and nothing from another line.":
    "如果该站点还生产 CBAM 范围之外的产品，请列出，以便核查员确认本报告的边界只涵盖 CBAM 产品，不含其他生产线的任何内容。",
  "If yes, give the responsible person at the receiving installation.":
    "如果是，请填写接收设施的负责人。",
  "If yes, give the sources and quantities, and the name and country of a supplier that is another installation.":
    "如果是，请填写来源和数量，以及作为另一设施的供应方的名称和国家。",
  "If yes, name it.": "如果是，请注明名称。",
  "If yes, name the gases and the five biggest sources it covers.":
    "如果是，请注明气体及其涵盖的五大排放源。",
  "If yes, name the installations and enter the heat quantities in the monthly data.":
    "如果是，请注明设施，并在月度数据中录入热量。",
  "If yes, name the installations.": "如果是，请注明设施。",
