  "Ready. Your free trial leaves the monitoring plan out of the package.":
    "已就绪。免费试用期的资料包不含监测计划。",
  "real data vs fallback": "实际数据与备选值对比",
  "Receipt for paper and printer ink. Nothing on it relates to emissions, energy or production.":
    "纸张和打印墨水的收据。与排放、能源或产量无关。",
  Received: "已收到",
  "Received — not usable yet": "已收到 — 尚不可用",
  "Received this month": "本月收到",
  Recently: "最近",
  recommended: "推荐",
  "Recorded — the exporter will confirm this is a new installation.":
    "已记录 — 出口商将确认这是新设施。",
  "Recorded as a CLAIMED deduction. Certrace does not subtract it from any liability figure: Thailand's THB 200/tCO₂e sits inside the oil excise structure rather than as a standalone carbon tax, and whether the EU accepts it under Art. 9 of Reg. (EU) 2023/956 is not settled. Budget as though it will not be accepted, and present it to your verifier with its instrument type and receipt.":
    "已记录为申报的扣减。Certrace 不会从任何应付数字中扣除它：泰国每吨 CO₂e 200 泰铢包含在石油消费税结构中，而非独立碳税，欧盟是否依第 2023/956 号法规第 9 条接受尚无定论。请按不会被接受来预算，并连同其工具类型和凭证向您的核查员说明。",
  "Recorded with your reason and included in the verification dossier.":
    "已连同您的理由记录，并纳入核查档案。",
  "Reduce the estimated share in the MMD's data-gap register":
    "在 MMD 的数据缺口登记中降低估算占比",
  "Reducing agent": "还原剂",
  "Regenerated from the sealed dataset — same figures, checkable hash.":
    "由已封存的数据集重新生成 — 数字相同，哈希可校验。",
  "Register them here once and their monthly data lands in your inbox instead of going out to a supplier.":
    "在此登记一次，它们的月度数据就会进入您的收件箱，而不是发给供应商。",
  "Reheat-furnace and finishing fuel on site, which is small next to what the steel already carries.":
    "站内再加热炉和精整用燃料，与钢材已带有的排放相比很小。",
  "Reheat-furnace fuel. Small next to what the input already carries.":
    "再加热炉燃料。与投入物已带有的排放相比很小。",
  "Relevant precursors & their embedded emissions": "相关前体及其隐含排放",
  "Relying on a default for a direct precursor therefore tends to raise the overall figure for this product, and it can end up close to — or even above — the default value for the finished good itself.":
    "因此，对直接前体依赖默认值往往会抬高本产品的总数，甚至可能接近 — 乃至超过 — 成品自身的默认值。",
  "Relying on a default for a direct precursor therefore tends to raise the overall figure for this product, and it can end up close to — or even above — the default value for the finished good itself. An actual value, verified at the precursor's installation, may be lower.":
    "因此，对直接前体依赖默认值往往会抬高本产品的总数，甚至可能接近 — 乃至超过 — 成品自身的默认值。在前体设施处经核查的实际值可能更低。",
  "Remelt and casting fuel. The lowest-intensity aluminium route.":
    "重熔和铸造用燃料。碳强度最低的铝路线。",
  "Reminder sent — response overdue": "已发送提醒 — 回复已逾期",
  "Reminder sent to {name}.": "已向 {name} 发送提醒。",
