  "Saved as a draft": "已保存为草稿",
  "Saved as draft": "已保存为草稿",
  "Saved to your directory — no onboarding needed":
    "已保存到您的名录 — 无需入驻",
  "Saved to your supplier directory — no onboarding needed.":
    "已保存到您的供应商名录 — 无需入驻。",
  "Saved vs defaults": "相对默认值节省",
  "Say what is done when a review finds an error or an instrument is out of tolerance.":
    "请说明复核发现错误或仪器超出公差时会怎么处理。",
  "Say where an error could enter between the first reading and the reported figure, and what is done about it.":
    "请说明从首次读数到报告数字之间，哪里可能出现错误，以及如何处理。",
  "Say where, and how an old version is told from the current one.":
    "请说明保存位置，以及如何区分旧版本与现行版本。",
  "Say whether any zero-rated fuel (biomass that meets the sustainability criteria) is used, and how you demonstrate it.":
    "请说明是否使用任何零排放因子燃料（满足可持续标准的生物质），以及如何证明。",
  "Say whether CO₂ is captured, stored or used elsewhere.":
    "请说明 CO₂ 是否在其他地方被捕集、封存或利用。",
  "Say whether CO₂ is transferred elsewhere.": "请说明 CO₂ 是否转移至别处。",
  "Say whether continuous emissions measurement is used.":
    "请说明是否使用连续排放监测。",
  "Say whether electricity comes from more than one source.":
    "请说明电力是否来自多个来源。",
  "Say whether electricity is generated inside the installation — by co-generation or separate generation, from fossil or renewable sources, and whether it leaves a production process.":
    "请说明设施内是否发电 — 热电联产或单独发电、化石或可再生来源，以及是否离开某个生产工艺。",
  "Say whether electricity is generated inside the installation and, if so, how.":
    "请说明设施内是否发电，若是，如何发电。",
  "Say whether measurable heat is bought from or sold to another installation.":
    "请说明是否向其他设施购买或出售可测量的热能。",
  "Say whether measurable heat is imported or exported.":
    "请说明是否进口或出口可测量的热能。",
  "Say whether waste gases are produced and used here, or imported from or exported to other installations.":
    "请说明此处是否产生并使用废气，或与其他设施进出口废气。",
  "Say whether waste gases are produced and used here, or imported or exported.":
    "请说明此处是否产生并使用废气，或进出口废气。",
  "Say which supply you have and where it is metered.":
    "请说明您采用哪种供电方式，以及在何处计量。",
  "Say who records, who checks and who approves, and how those people are trained.":
    "请说明谁负责记录、谁负责检查、谁负责批准，以及这些人如何接受培训。",
  "Scanned electricity bill for April 2026. Several digits are smudged; the total kWh is partly obscured and a handwritten note repeats it with a question mark.":
    "2026 年 4 月电费账单的扫描件。有几个数字模糊不清；总千瓦时部分被遮挡，手写备注重复了该数字并加了问号。",
