  "Secondary aluminium": "再生铝",
  "Secondary melting — aluminium scrap is melted and cast. Unwrought aluminium bought in and added is a precursor, not scrap.":
    "二次熔炼 — 铝废料经熔化铸造。外购并加入的未锻轧铝属于前体，不是废料。",
  "Section 3.4 is assembled out of three tabs; one thin tab leaves four sections short. This says which sections.":
    "第 3.4 节由三个标签页拼成；一个薄弱的标签页会让四个章节不足。这里说明是哪些章节。",
  "Section by section, in the order it prints. Nothing here is a gate — it is so you can see what a verifier will and will not find.":
    "按打印顺序逐章列出。这里没有任何关口 — 只是让您看到核查员会找到什么、找不到什么。",
  "Sector rules applied automatically": "自动应用行业规则",
