  "Should I use default or actual values?": "我应该使用默认值还是实际值？",
  "Show a worked example": "显示示例",
  "Show archived product reports — off the dashboard, out of the Inbox, not counted in Reports. Nothing is deleted.":
    "显示已归档的产品报告 — 不在仪表盘上、不在收件箱中、不计入报告。不会删除任何内容。",
  "Show archived workspaces — off the dashboard, out of the Inbox, not counted in Reports.":
    "显示已归档的工作区 — 不在仪表盘上、不在收件箱中、不计入报告。",
  "Show archived workspaces — off the dashboard, out of the Inbox, not counted in Reports. Nothing is deleted.":
    "显示已归档的工作区 — 不在仪表盘上、不在收件箱中、不计入报告。不会删除任何内容。",
