  "Signature voids if the figures change": "数字一变，签名即失效",
  "signed off": "已签署",
  "Signed off": "已签署",
  "Single 115 kV incoming feeder into substation SS-01, revenue meter PEA-88214, read monthly against the PEA invoice. Furnace load is sub-metered at E-101 but the reported figure is the incoming feeder, because that is the figure the invoice evidences.":
    "一条 115 kV 进线接入变电站 SS-01，计费表 PEA-88214，每月对照 PEA 发票读取。炉子负荷在 E-101 处分表计量，但报告的是进线数字，因为发票证明的是该数字。",
  Sintering: "烧结",
  "Sintering — iron ore is agglomerated by burning fuel. Most of the CO₂ comes from the fuel and the flux.":
    "烧结 — 铁矿石通过燃烧燃料而结块。大部分 CO₂ 来自燃料和熔剂。",
  Slope: "斜率",
  "Smart upload is on. Drop one file into the bar below — or choose one — and press send. I'll work out which product report and month it's for and what readings it holds, and ask only what I can't tell.":
    "智能上传已开启。把一个文件拖入下方输入栏 — 或选择一个 — 然后点击发送。我会判断它属于哪份产品报告和哪个月份、包含哪些读数，并且只问我无法判断的内容。",
  "Smelting route — only for primary (unwrought) aluminium from electrolysis":
    "冶炼路线 — 仅适用于电解法生产的原铝（未锻轧铝）",
  "Something else": "其他",
  "something is missing": "有缺失",
  "Source process": "来源工艺",
