  "UN location code of the site, e.g. THRYG":
    "站点的联合国地点代码，例如 THRYG",
  "UN/LOCODE of the location": "地点的 UN/LOCODE",
  "unchanged — a gap is a ratio, so scaling the year leaves it where it is":
    "不变 — 缺口是一个比率，把全年放大并不改变它",
  "United Kingdom": "英国",
  "United States": "美国",
  unknown: "未知",
