  "Whether waste gases are produced and used in the installation, or imported from or exported to other installations — which":
    "设施内是否产生并使用废气，或与其他设施进出口废气 — 具体是哪些",
  "Whether zero-rated fuels are used, and how the operator demonstrates that zero-rating applies":
    "是否使用零排放因子燃料，以及运营方如何证明适用零排放因子",
