  "Create your account.": "创建您的账户。",
  "Creating account…": "正在创建账户…",
  "I agree to Certrace's": "我同意 Certrace 的",
  "One account per company. Add teammates as seats once you're in.":
    "每家公司一个账户。进入后可把队友添加为席位。",
  "or sign up with email": "或使用邮箱注册",
  "Re-enter password": "再次输入密码",
  "Sign up with Google": "使用 Google 注册",
  "Terms of Service": "服务条款",
  "Back to declarations": "返回申报",
  "Open the supplier link instead": "改为打开供应商链接",
  "Add & invite": "添加并邀请",
  "Add a person": "添加人员",
  "e.g. Preeda C.": "例如 Preeda C.",
  Role: "角色",
  Team: "团队",
  "They join your team list and can be assigned to any check. We email them an invite with scoped, read-only access — they never see anything outside what you share.":
    "他们会加入您的团队名单，并可被分配到任何检查。我们会向他们发送邀请邮件，授予限定范围的只读权限 — 他们看不到您所分享之外的任何内容。",
  "6× faster filing": "申报快 6 倍",
  "94% avg completion": "平均完成率 94%",
  "Buyers don't wait. They pick whoever proves it first.":
    "买家不会等待。谁先拿出证明，他们就选谁。",
  "Certrace — go to certrace.co": "Certrace — 前往 certrace.co",
  Buyer: "买家",
  "Buyer name": "买家名称",
  "Contact person": "联系人",
  "Recorded here rather than on each shipment so it is typed once and is identical on every consignment — which is what lets their declarant reconcile what they received.":
    "记录在这里而不是每批货上，这样只需输入一次，且每批货完全一致 — 这使其申报人能够核对所收到的内容。",
  "Rotterdam Steel Import BV": "Rotterdam Steel Import BV",
  "The EU importer this consignment is going to. Recorded once, then picked on every shipment to them.":
    "这批货发往的欧盟进口商。记录一次，之后在发往他们的每批货中选取。",
  "The EU importer, as it appears on your invoice.":
    "欧盟进口商，与您发票上的一致。",
  "Where the importer is established.": "进口商的设立地。",
